select case when year(order_date) < 2024 then 'before_2024' when year(order_date) = 2024 then '2024' else 'after_2024' end as order_cohort, status, max(discount) - min(discount) as discount_range, max(order_date) as latest_order_date, min(amount) as min_amount from orders where customer_id = 17 and store_id = 19 group by case when year(order_date) < 2024 then 'before_2024' when year(order_date) = 2024 then '2024' else 'after_2024' end, status
